  --success:     #4ade80;
  --radius:      10px;
  --focus-ring:  0 0 0 3px #6c8fff80;
}

/* ── Skip link ───────────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 0;
  padding: .5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  border-radius: 0 0 var(--radius) 0;
  z-index: 9999;
  text-decoration: none;
}
.skip-link:focus { top: 0; }

/* ── Page layout ─────────────────────────────────────────────────────────── */
body {
  font-family: system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: grid;
  place-items: start center;
  padding: 2rem 1rem 4rem;
  line-height: 1.6;
}

header {
  width: 100%;
  max-width: 680px;
  margin-bottom: 2rem;
  text-align: center;
}

header h1 {
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  background: linear-gradient(135deg, #9ab3ff, #6c8fff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

header p {
  margin-top: .5rem;
  color: var(--text-muted);
  font-size: .95rem;
}

main { width: 100%; max-width: 680px; }

/* ── Form ────────────────────────────────────────────────────────────────── */
.quiz-form { display: flex; flex-direction: column; gap: 1.5rem; }

/* ── Question card (form-field) ──────────────────────────────────────────── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: border-color .2s;
}
.form-field:focus-within { border-color: var(--accent); }

.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  padding: 0;
  margin-bottom: .75rem;
  display: flex;
  align-items: baseline;
  gap: .4rem;
  width: 100%;
}

.question-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  border-radius: 50%;
  background: var(--accent-dark);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  flex-shrink: 0;
}

/* ── Help / error text ───────────────────────────────────────────────────── */
.help-text {
  font-size: .85rem;
  color: var(--text-muted);
  margin-bottom: .9rem;
  padding: .5rem .75rem;
  background: var(--surface-2);
  border-left: 3px solid var(--accent);
  border-radius: 0 6px 6px 0;
}

.error-text {
  font-size: .85rem;
  color: var(--error);
  margin-top: .75rem;
  display: flex;
  align-items: center;
  gap: .35rem;
}
.error-text::before { content: "⚠"; }

/* ── Checkbox options ────────────────────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.option-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .65rem .85rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: background .15s, border-color .15s;
  user-select: none;
}
.option-label:hover { background: var(--surface-2); border-color: var(--accent); }

/* hide the native checkbox visually but keep it accessible */
.option-label input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  border: 2px solid var(--text-muted);
  border-radius: 4px;
  flex-shrink: 0;
  position: relative;
  cursor: pointer;
  transition: background .15s, border-color .15s;
  background: transparent;
}

.option-label input[type="checkbox"]:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.option-label input[type="checkbox"]:checked::after {
  content: "";
  display: block;
  position: absolute;
  top: 1px;
  left: 4px;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

/* checked state highlights the row */
.option-label:has(input:checked) {
  background: #1e2640;
  border-color: var(--accent);
}

/* Focus ring on checkbox */
.option-label input[type="checkbox"]:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* invalid state */
.form-field.invalid .option-label input[type="checkbox"] {
  border-color: var(--error);
}
.form-field.invalid fieldset { /* nothing extra needed */ }

/* ── Submit button ───────────────────────────────────────────────────────── */
.submit-btn {
  align-self: flex-end;
  padding: .75rem 2rem;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background .2s, transform .1s;
}
.submit-btn:hover { background: var(--accent-dark); }
.submit-btn:active { transform: scale(.98); }
.submit-btn:focus-visible { outline: none; box-shadow: var(--focus-ring); }

/* ── Results status region ───────────────────────────────────────────────── */
#quiz-status {
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius);
  font-size: .95rem;
  display: none;
}
#quiz-status.show { display: block; }
#quiz-status.correct-all {
  background: #0f2d1e;
  border: 1px solid var(--success);
  color: var(--success);
}
#quiz-status.partial {
  background: #2a1e0f;
  border: 1px solid #f5a623;
  color: #f5a623;
}
#quiz-status.none {
  background: #2d0f0f;
  border: 1px solid var(--error);
  color: var(--error);
}

/* ── Answer feedback per question ────────────────────────────────────────── */
.option-label.correct-answer { border-color: var(--success) !important; background: #0f2d1e !important; }
.option-label.wrong-answer   { border-color: var(--error) !important;   background: #2d0f0f !important; }
.option-label .answer-tag {
  margin-left: auto;
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.option-label.correct-answer .answer-tag { color: var(--success); }
.option-label.wrong-answer   .answer-tag { color: var(--error); }

/* ── Forced Colors (Windows High Contrast) ───────────────────────────────── */
@media (forced-colors: active) {
  .option-label input[type="checkbox"]:checked { forced-color-adjust: none; }
  .submit-btn { forced-color-adjust: none; }
}

/* ── Reduced motion ──────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow / narrow viewport ────────────────────────────────────────────── */
@media (max-width: 400px) {
  .form-field { padding: 1rem; }
  .submit-btn { width: 100%; align-self: stretch; }
}
