AssistantMessageToolRequest(name='create', tool_call_id='tooluse_5WoaFUi98fHF3tkCtvwnAn', arguments={'file_text': '(() => {
  // Correct answers per question (by checkbox value)
  const CORRECT = {
    q1: ["c", "java"],
    q2: ["javascript", "typescript", "html-css"],
    q3: ["java", "python", "cpp"],
  };

  const form = document.getElementById("quiz-form");
  const statusEl = document.getElementById("quiz-status");

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    let allValid = true;

    // Clear previous feedback
    document.querySelectorAll(".form-field").forEach((field) => {
      field.classList.remove("invalid");
      field.querySelector(".error-text").hidden = true;
      field.querySelectorAll(".option-label").forEach((lbl) => {
        lbl.classList.remove("correct-answer", "wrong-answer");
        const tag = lbl.querySelector(".answer-tag");
        if (tag) tag.remove();
      });
    });
    statusEl.className = "";
    statusEl.classList.remove("show");

    // Validate: each question needs at least one selection
    let firstInvalid = null;
    Object.keys(CORRECT).forEach((qid) => {
      const fieldset = document.getElementById(`fieldset-${qid}`);
      const field = fieldset.closest(".form-field");
      const checked = [...fieldset.querySelectorAll("input:checked")].map(
        (i) => i.value
      );
      if (checked.length === 0) {
        allValid = false;
        field.classList.add("invalid");
        field.querySelector(".error-text").hidden = false;
        if (!firstInvalid) firstInvalid = fieldset.querySelector("input");
      }
    });

    if (!allValid) {
      firstInvalid.focus();
      return;
    }

    // Score and show per-answer feedback
    let totalCorrect = 0;
    Object.entries(CORRECT).forEach(([qid, correct]) => {
      const fieldset = document.getElementById(`fieldset-${qid}`);
      const checked = new Set(
        [...fieldset.querySelectorAll("input:checked")].map((i) => i.value)
      );
      const correctSet = new Set(correct);

      // A question is "fully correct" when checked === correct (exact match)
      const isFullyCorrect =
        checked.size === correctSet.size &&
        [...checked].every((v) => correctSet.has(v));
      if (isFullyCorrect) totalCorrect++;

      fieldset.querySelectorAll("input").forEach((input) => {
        const lbl = input.closest(".option-label");
        const isCorrect = correctSet.has(input.value);
        const wasChecked = checked.has(input.value);
        const tag = document.createElement("span");
        tag.className = "answer-tag";
        tag.setAttribute("aria-hidden", "true");

        if (wasChecked && isCorrect) {
          lbl.classList.add("correct-answer");
          tag.textContent = "✓ correct";
        } else if (wasChecked && !isCorrect) {
          lbl.classList.add("wrong-answer");
          tag.textContent = "✗ wrong";
        } else if (!wasChecked && isCorrect) {
          lbl.classList.add("correct-answer");
          tag.textContent = "← missed";
        }
        if (tag.textContent) lbl.appendChild(tag);
      });
    });

    // Disable form after submission
    form.querySelectorAll("input, button").forEach((el) => (el.disabled = true));

    // Show summary status message (live region)
    const total = Object.keys(CORRECT).length;
    statusEl.classList.add("show");
    if (totalCorrect === total) {
      statusEl.className = "show correct-all";
      statusEl.textContent = `🎉 Perfect score! You got all ${total} questions right.`;
    } else if (totalCorrect > 0) {
      statusEl.className = "show partial";
      statusEl.textContent = `You got ${totalCorrect} out of ${total} questions fully correct. Review the highlighted answers above.`;
    } else {
      statusEl.className = "show none";
      statusEl.textContent = `No questions were fully correct. Review the highlighted answers above and try again.`;
    }
    statusEl.focus();
  });
})();
