const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');
const js = fs.readFileSync('quiz.js','utf8');
const css = fs.readFileSync('style.css','utf8');

// Basic sanity checks
const checks = [
  ['Has skip link',              html.includes('skip-link')],
  ['Has main landmark',          html.includes('<main')],
  ['Has h1',                     html.includes('<h1>')],
  ['Has fieldsets',              (html.match(/<fieldset/g)||[]).length === 3],
  ['Has legends',                (html.match(/<legend/g)||[]).length === 3],
  ['Has help text q1',           html.includes('q1-help')],
  ['aria-describedby on fieldset', html.includes('aria-describedby')],
  ['Has live region',            html.includes('aria-live')],
  ['Has submit button',          html.includes('type=\"submit\"')],
  ['Error text present',         html.includes('class=\"error-text\"')],
  ['Native checkboxes',          (html.match(/type=\"checkbox\"/g)||[]).length === 12],
  ['Focus visible in CSS',       css.includes('focus-visible')],
  ['Error text hidden attr',     html.includes('hidden')],
  ['CORRECT keys match fieldset ids', js.includes('q1') && js.includes('q2') && js.includes('q3')],
];

let pass = 0;
checks.forEach(([name, ok]) => {
  console.log((ok ? '✓' : '✗') + ' ' + name);
  if (ok) pass++;
});
console.log('\n' + pass + '/' + checks.length + ' checks passed');
"
