  display: grid;
  place-items: start center;
  padding: 2rem 1rem 4rem;
  line-height: 1.6;
}

header {
  width: 100%;
  max-width: 680px;
  margin-bottom: 2rem;
  text-align: center;
}

header h1 {
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  background: linear-gradient(135deg, #9ab3ff, #6c8fff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

header p {
  margin-top: .5rem;
  color: var(--text-muted);
  font-size: .95rem;
}

main { width: 100%; max-width: 680px; }

/* ── Form ────────────────────────────────────────────────────────────────── */
.quiz-form { display: flex; flex-direction: column; gap: 1.5rem; }

/* ── Question card (form-field) ──────────────────────────────────────────── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: border-color .2s;
}
.form-field:focus-within { border-color: var(--accent); }

.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  padding: 0;
  margin-bottom: .75rem;
  display: flex;
  align-items: baseline;
  gap: .4rem;
  width: 100%;
}

.question-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  border-radius: 50%;
  background: var(--accent-dark);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  flex-shrink: 0;
}

/* ── Help / error text ───────────────────────────────────────────────────── */
.help-text {
  font-size: .85rem;
  color: var(--text-muted);
  margin-bottom: .9rem;
  padding: .5rem .75rem;
  background: var(--surface-2);
  border-left: 3px solid var(--accent);
  border-radius: 0 6px 6px 0;
}

.error-text {
  font-size: .85rem;
  color: var(--error);
  margin-top: .75rem;
  display: flex;
  align-items: center;
  gap: .35rem;
}
.error-text::before { content: "⚠"; }

/* ── Checkbox options ────────────────────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.option-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .65rem .85rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  cursor: pointer;
  transition: background .15s, border-color .15s;
  user-select: none;
}
.option-label:hover { background: var(--surface-2); border-color: var(--accent); }

