  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

/* checked state highlights the row */
.option-label:has(input:checked) {
  background: #1e2640;
  border-color: var(--accent);
}

/* Focus ring on checkbox */
.option-label input[type="checkbox"]:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* invalid state */
.form-field.invalid .option-label input[type="checkbox"] {
  border-color: var(--error);
}
.form-field.invalid fieldset { /* nothing extra needed */ }

/* ── Submit button ───────────────────────────────────────────────────────── */
.submit-btn {
  align-self: flex-end;
  padding: .75rem 2rem;
  border: none;
  border-radius: var(--radius);
  background: var(--btn-bg);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background .2s, transform .1s;
}
.submit-btn:hover { background: var(--btn-hover); }
.submit-btn:active { transform: scale(.98); }
.submit-btn:focus-visible { outline: none; box-shadow: var(--focus-ring); }

/* ── Results status region ───────────────────────────────────────────────── */
#quiz-status {
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius);
  font-size: .95rem;
  display: none;
}
#quiz-status.show { display: block; }
#quiz-status.correct-all {
  background: #0f2d1e;
  border: 1px solid var(--success);
  color: var(--success);
}
#quiz-status.partial {
  background: #2a1e0f;
  border: 1px solid #f5a623;
  color: #f5a623;
}
#quiz-status.none {
  background: #2d0f0f;
  border: 1px solid var(--error);
  color: var(--error);
}

/* ── Answer feedback per question ────────────────────────────────────────── */
.option-label.correct-answer { border-color: var(--success) !important; background: #0f2d1e !important; }
.option-label.wrong-answer   { border-color: var(--error) !important;   background: #2d0f0f !important; }
.option-label .answer-tag {
  margin-left: auto;
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.option-label.correct-answer .answer-tag { color: var(--success); }
.option-label.wrong-answer   .answer-tag { color: var(--error); }

/* ── Forced Colors (Windows High Contrast) ───────────────────────────────── */
@media (forced-colors: active) {
  .option-label input[type="checkbox"]:checked { forced-color-adjust: none; }
  .submit-btn { forced-color-adjust: none; }
}

/* ── Reduced motion ──────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow / narrow viewport ────────────────────────────────────────────── */
@media (max-width: 400px) {
  .form-field { padding: 1rem; }
  .submit-btn { width: 100%; align-self: stretch; }
}
